package com.codepilot1c.core.edt.compare;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
import com._1c.g5.v8.dt.moxel.*;
import com._1c.g5.v8.dt.moxel.content.ContentFactory;
public class SpreadsheetSemanticMergeTest {
    private SpreadsheetDocument doc(String text){var d=MoxelFactory.eINSTANCE.createSpreadsheetDocument();d.getFormats().add(MoxelFactory.eINSTANCE.createFormat());var row=MoxelFactory.eINSTANCE.createRow();var cell=MoxelFactory.eINSTANCE.createCell();var t=ContentFactory.eINSTANCE.createLocalString();t.getContent().put("#",text);cell.setText(t);row.getCells().put(0,cell);d.getRows().put(0,row);return d;}
    private Cell cell(SpreadsheetDocument d){return d.getRows().get(Integer.valueOf(0)).getCells().get(Integer.valueOf(0));}
    private String text(SpreadsheetDocument d){return cell(d).getText().getContent().get("#");}
    private SpreadsheetSemanticMerge.Analysis run(SpreadsheetDocument b,SpreadsheetDocument m,SpreadsheetDocument o,SpreadsheetDocument r){return SpreadsheetSemanticMerge.analyze(b,m,o,r,Map.of(),true);}
    @Test public void independentCellPropertiesMerge(){var b=doc("base");var m=doc("local");var o=doc("base");cell(o).setParameter("external");var a=run(b,m,o,null);assertEquals(0,a.unresolved());assertEquals("local",text(a.result()));assertEquals("external",cell(a.result()).getParameter());assertEquals("local",text(m));assertNull(cell(m).getParameter());}
    @Test public void sameChangeIsNotConflict(){assertEquals(0,run(doc("base"),doc("same"),doc("same"),null).unresolved());}
    @Test public void conflictingTextRemainsMainUntilExplicitResolution(){var b=doc("base");var m=doc("local");var o=doc("remote");var a=run(b,m,o,null);assertEquals(1,a.unresolved());assertEquals("local",text(a.result()));var id=a.differences().stream().filter(SpreadsheetSemanticMerge.Difference::conflict).findFirst().orElseThrow().id();var resolved=SpreadsheetSemanticMerge.analyze(b,m,o,null,Map.of(id,"OTHER"),true);assertEquals(0,resolved.unresolved());assertEquals("remote",text(resolved.result()));}
    @Test public void explicitMainResolvesUnchangedValue(){var b=doc("base");var m=doc("local");var o=doc("remote");var a=run(b,m,o,null);var id=a.differences().stream().filter(SpreadsheetSemanticMerge.Difference::conflict).findFirst().orElseThrow().id();assertEquals(0,SpreadsheetSemanticMerge.analyze(b,m,o,null,Map.of(id,"MAIN"),true).unresolved());}
    @Test public void existingManualResultIsPreserved(){var a=run(doc("base"),doc("base"),doc("remote"),doc("manual"));assertEquals("manual",text(a.result()));assertTrue(a.differences().stream().anyMatch(d->d.origin().equals("MANUAL")));}
    @Test public void noAncestorNeverGuessesAuthor(){var a=run(null,doc("one"),doc("two"),null);assertFalse(a.threeWay());assertEquals(1,a.unresolved());assertEquals("one",text(a.result()));}
    @Test public void deleteVersusEditIsConflict(){var b=doc("base");var m=doc("base");m.getRows().clear();var a=run(b,m,doc("edited"),null);assertTrue(a.unresolved()>0);assertTrue(a.result().getRows().isEmpty());}
    @Test public void shiftedRowRequiresStructuralDecision(){var b=doc("anchor");var o=doc("anchor");var row=o.getRows().removeKey(0);o.getRows().put(1,row);var a=run(b,doc("anchor"),o,null);assertEquals("/structure",a.differences().get(0).path());assertEquals(1,a.unresolved());}
    @Test public void reorderedEquivalentFormatPoolHasNoDifference(){var b=doc("base");var m=doc("base");var o=doc("base");var extra=MoxelFactory.eINSTANCE.createFormat();extra.setWidth(44);o.getFormats().add(0,extra);cell(o).setFormatIndex(1);o.getRows().get(Integer.valueOf(0)).setFormatIndex(1);o.setDefaultFormatIndex(1);assertEquals(0,run(b,m,o,null).differences().size());}
    @Test public void independentFormatPropertiesMerge(){var b=doc("base");var m=doc("base");var o=doc("base");m.getFormats().get(0).setWidth(80);o.getFormats().get(0).setHeight(30);var a=run(b,m,o,null);assertEquals(0,a.unresolved());var f=a.result().getFormats().get(cell(a.result()).getFormatIndex());assertEquals(80,f.getWidth());assertEquals(30,f.getHeight());}
    @Test public void previousResolutionDoesNotOverwriteLaterManualEdit(){var b=doc("base");var m=doc("one");var o=doc("two");var a=run(b,m,o,null);var id=a.differences().stream().filter(SpreadsheetSemanticMerge.Difference::conflict).findFirst().orElseThrow().id();var edited=SpreadsheetSemanticMerge.analyze(b,m,o,doc("user edit"),Map.of(id,"MAIN"),true,Set.of());assertEquals("user edit",text(edited.result()));assertEquals(0,edited.unresolved());}
    @Test public void independentExtentGrowthUsesMaximum(){var b=doc("base");b.setHeight(1);var m=doc("base");m.setHeight(2);var o=doc("base");o.setHeight(3);var a=run(b,m,o,null);assertEquals(0,a.unresolved());assertEquals(3,a.result().getHeight());}
    @Test public void sharedColumnBandRemainsTheSameNativeObject(){var b=doc("base");var columns=MoxelFactory.eINSTANCE.createColumns();columns.setColumnsId(java.util.UUID.randomUUID());b.getAllColumns().add(columns);b.setColumns(columns);b.getRows().get(Integer.valueOf(0)).setColumns(columns);var a=run(b,b,b,null);assertSame(a.result().getColumns(),a.result().getAllColumns().get(0));assertSame(a.result().getColumns(),a.result().getRows().get(Integer.valueOf(0)).getColumns());}
    @Test public void implicitNegativePoolSentinelsRemainUnset(){var a=run(doc("base"),doc("one"),doc("base"),null);for(var format:a.result().getFormats()){assertFalse(format.isSetFont());assertFalse(format.isSetLeftBorder());assertFalse(format.isSetBackColor());}}
    @Test public void oneSidedNamedAreaIsPreserved(){var b=doc("base");var m=doc("local");var o=doc("base");var area=MoxelFactory.eINSTANCE.createNamedItemCells();var rectArea=MoxelFactory.eINSTANCE.createRectArea();var rect=MoxelFactory.eINSTANCE.createRect();rect.setX(1);rect.setY(2);rectArea.setPosition(rect);area.setArea(rectArea);o.getNamedItems().put("Header",area);var a=run(b,m,o,null);assertEquals(0,a.unresolved());assertNotNull(a.result().getNamedItems().get("Header"));assertEquals("local",text(a.result()));}
    @Test public void divergentMergedRegionsRequireExplicitDecision(){var b=doc("base");var m=doc("base");var o=doc("base");for(var d:List.of(m,o)){var merge=MoxelFactory.eINSTANCE.createMerge();var rect=MoxelFactory.eINSTANCE.createRect();rect.setWidth(d==m?1:2);merge.setPosition(rect);d.getMerges().add(merge);}var a=run(b,m,o,null);assertTrue(a.differences().stream().anyMatch(d->d.path().equals("/merges")&&d.conflict()&&!d.resolved()));}
    @Test public void drawingsAreNotDropped(){var b=doc("base");var m=doc("local");var o=doc("base");var picture=MoxelFactory.eINSTANCE.createPictureDrawing();picture.setDrawingId(7);o.getDrawings().add(picture);var a=run(b,m,o,null);assertEquals(1,a.result().getDrawings().size());assertEquals(7,a.result().getDrawings().get(0).getDrawingId());assertEquals("local",text(a.result()));}
    @Test public void columnMovementIsStructuralConflict(){var b=doc("anchor");var m=doc("anchor");var o=doc("anchor");var row=o.getRows().get(Integer.valueOf(0));var value=row.getCells().removeKey(0);row.getCells().put(1,value);var a=run(b,m,o,null);assertEquals("/structure",a.differences().get(0).path());assertEquals(1,a.unresolved());}
    @Test public void differentAdditionsAtSameNewCoordinateConflictAsAUnit(){var b=doc("base");var m=doc("base");var o=doc("base");for(var d:List.of(m,o)){var row=MoxelFactory.eINSTANCE.createRow();var cell=MoxelFactory.eINSTANCE.createCell();cell.setParameter(d==m?"local":"remote");row.getCells().put(0,cell);d.getRows().put(1,row);}var a=run(b,m,o,null);assertTrue(a.differences().stream().anyMatch(d->d.path().equals("/rows/java.lang.Integer:1")&&d.conflict()));}
    @Test public void nativeEmptyPlaceholderRowIsNotAnAddAddConflict(){var b=doc("base");var m=doc("base");var o=doc("base");var row=MoxelFactory.eINSTANCE.createRow();var c=MoxelFactory.eINSTANCE.createCell();c.setParameter("local");row.getCells().put(0,c);m.getRows().put(1,row);o.getRows().put(1,MoxelFactory.eINSTANCE.createRow());var a=run(b,m,o,null);assertEquals(0,a.unresolved());assertEquals("local",a.result().getRows().get(Integer.valueOf(1)).getCells().get(Integer.valueOf(0)).getParameter());}
    @Test public void pooledRgbColorIsPreservedAlongsideIndependentText(){var b=doc("base");var m=doc("local");var o=doc("base");var color=com._1c.g5.v8.dt.mcore.McoreFactory.eINSTANCE.createColorDef();color.setRed(20);color.setGreen(40);color.setBlue(60);o.getColors().add(color);o.getFormats().get(0).setBackColor(0);var a=run(b,m,o,null);assertEquals(0,a.unresolved());var format=a.result().getFormats().get(cell(a.result()).getFormatIndex());var actual=a.result().getColors().get(format.getBackColor());assertEquals(20,actual.red());assertEquals(40,actual.green());assertEquals(60,actual.blue());assertEquals("local",text(a.result()));assertEquals(1,o.getColors().size());}
    @Test public void formatZeroRemainsImplicitNeutralForNativeSerializer(){var b=doc("base");var m=doc("local");var o=doc("base");o.getFormats().get(0).setWidth(80);var a=run(b,m,o,null);assertFalse(a.result().getFormats().get(0).isSetWidth());assertTrue(cell(a.result()).getFormatIndex()>0);assertEquals(80,a.result().getFormats().get(cell(a.result()).getFormatIndex()).getWidth());}
    @Test public void equalIndependentColumnBandsAreNotCollapsed(){var d=doc("base");var a=MoxelFactory.eINSTANCE.createColumns();var b=MoxelFactory.eINSTANCE.createColumns();a.setColumnsId(java.util.UUID.randomUUID());b.setColumnsId(java.util.UUID.randomUUID());d.getAllColumns().add(a);d.getAllColumns().add(b);d.setColumns(a);d.getRows().get(Integer.valueOf(0)).setColumns(b);var result=run(d,d,d,null).result();assertEquals(2,result.getAllColumns().size());assertNotSame(result.getColumns(),result.getRows().get(Integer.valueOf(0)).getColumns());assertEquals(b.getColumnsId(),result.getRows().get(Integer.valueOf(0)).getColumns().getColumnsId());}
    @Test public void sharedBandPropertiesMergeOnceAndAllRowsKeepTheLink(){var b=doc("base");var m=doc("base");var o=doc("base");var id=java.util.UUID.randomUUID();for(var d:List.of(b,m,o)){var band=MoxelFactory.eINSTANCE.createColumns();band.setColumnsId(id);band.setSize(1);d.getAllColumns().add(band);d.setColumns(band);d.getRows().get(Integer.valueOf(0)).setColumns(band);}m.getFormats().get(0).setWidth(80);o.getFormats().get(0).setHeight(30);var a=run(b,m,o,null);assertEquals(0,a.unresolved());assertSame(a.result().getColumns(),a.result().getRows().get(Integer.valueOf(0)).getColumns());var f=a.result().getFormats().get(a.result().getColumns().getFormatIndex());assertEquals(80,f.getWidth());assertEquals(30,f.getHeight());}
    @Test public void positionsAreOneBasedAndIdsStable(){var a=run(doc("base"),doc("one"),doc("two"),null);var d=a.differences().get(0);assertEquals(1,d.row());assertEquals(1,d.col());assertEquals(d.id(),run(doc("base"),doc("one"),doc("two"),null).differences().get(0).id());}
    @Test public void localizedTextCannotCollideWithMapDelimiters(){var b=doc("x, java.lang.String:ru=y");var m=doc("x, java.lang.String:ru=y");var o=doc("x");cell(o).getText().getContent().put("ru","y");var a=run(b,m,o,null);assertEquals("x",text(a.result()));assertEquals("y",cell(a.result()).getText().getContent().get("ru"));assertFalse(a.differences().isEmpty());}
    @Test public void manualRowShiftBlocksCoordinateBasedAutomaticEdits(){var b=doc("anchor");var m=doc("anchor");var o=doc("anchor");cell(o).setParameter("source edit");var r=doc("filler");var moved=doc("anchor").getRows().removeKey(0);r.getRows().put(1,moved);var a=run(b,m,o,r);assertEquals("/structure",a.differences().get(0).path());assertEquals(1,a.unresolved());assertEquals("filler",text(a.result()));assertNull(cell(a.result()).getParameter());assertEquals("anchor",a.result().getRows().get(Integer.valueOf(1)).getCells().get(Integer.valueOf(0)).getText().getContent().get("#"));}
    @Test public void priorityModesKeepIndependentPropertiesAndChooseOnlyConflictingText(){
        var b=doc("base");var m=doc("main");var o=doc("other");cell(m).setParameter("local parameter");cell(o).getText().getContent().put("ru","source translation");
        for(String mode:List.of("PRIORITY_MAIN","PRIORITY_OTHER")){
            var a=SpreadsheetSemanticMerge.applyMode(b,m,o,mode);assertEquals(0,a.analysis().unresolved());assertEquals(mode.endsWith("MAIN")?"main":"other",text(a.analysis().result()));
            assertEquals("local parameter",cell(a.analysis().result()).getParameter());assertEquals("source translation",cell(a.analysis().result()).getText().getContent().get("ru"));assertFalse(a.decisions().isEmpty());
        }
        assertEquals("main",text(m));assertNull(cell(m).getText().getContent().get("ru"));assertNull(cell(o).getParameter());
    }
    @Test public void wholeSideModesDoNotMergePropertiesFromOtherSide(){
        var b=doc("base");var m=doc("main");var o=doc("other");cell(o).setParameter("remote");
        var left=SpreadsheetSemanticMerge.applyMode(b,m,o,"MAIN");assertEquals("main",text(left.analysis().result()));assertNull(cell(left.analysis().result()).getParameter());assertEquals(0,left.analysis().unresolved());
        var right=SpreadsheetSemanticMerge.applyMode(b,m,o,"OTHER");assertEquals("other",text(right.analysis().result()));assertEquals("remote",cell(right.analysis().result()).getParameter());assertEquals(0,right.analysis().unresolved());
    }
    @Test public void priorityWithoutAncestorUsesExplicitSideForAmbiguousDifferences(){var a=SpreadsheetSemanticMerge.applyMode(null,doc("left"),doc("right"),"PRIORITY_OTHER");assertFalse(a.analysis().threeWay());assertEquals("right",text(a.analysis().result()));assertEquals(0,a.analysis().unresolved());}
    @Test public void priorityDoesNotGuessAcrossShiftedRows(){var b=doc("anchor");var m=doc("anchor");var o=doc("anchor");o.getRows().put(1,o.getRows().removeKey(0));for(String mode:List.of("PRIORITY_MAIN","PRIORITY_OTHER")){var a=SpreadsheetSemanticMerge.applyMode(b,m,o,mode);assertEquals(1,a.analysis().unresolved());assertTrue(a.decisions().isEmpty());assertEquals("anchor",text(a.analysis().result()));}}
    @Test public void wholeOtherExplicitlyResolvesStructuralConflict(){var b=doc("anchor");var o=doc("anchor");o.getRows().put(1,o.getRows().removeKey(0));var a=SpreadsheetSemanticMerge.applyMode(b,doc("anchor"),o,"OTHER");assertEquals(0,a.analysis().unresolved());assertNull(a.analysis().result().getRows().get(Integer.valueOf(0)));assertNotNull(a.analysis().result().getRows().get(Integer.valueOf(1)));}
    @Test public void unknownModeIsRejected(){assertThrows(IllegalArgumentException.class,()->SpreadsheetSemanticMerge.applyMode(null,doc("left"),doc("right"),"random"));assertThrows(IllegalArgumentException.class,()->SpreadsheetSemanticMerge.applyMode(null,doc("left"),doc("right"),null));}
    private SpreadsheetDocument repeated(boolean columns,int count){var d=MoxelFactory.eINSTANCE.createSpreadsheetDocument();d.getFormats().add(MoxelFactory.eINSTANCE.createFormat());for(int i=0;i<count;i++){int rowIndex=columns?0:i;var row=d.getRows().get(Integer.valueOf(rowIndex));if(row==null){row=MoxelFactory.eINSTANCE.createRow();d.getRows().put(rowIndex,row);}var c=MoxelFactory.eINSTANCE.createCell();var t=ContentFactory.eINSTANCE.createLocalString();t.getContent().put("#",i==0?"HEADER":"X");c.setText(t);row.getCells().put(columns?i:0,c);}return d;}
    @Test public void repeatedRowInsertionWithStableHeaderIsStructuralConflict(){var b=repeated(false,3);var m=repeated(false,3);var o=repeated(false,4);var f=MoxelFactory.eINSTANCE.createFormat();f.setWidth(42);m.getFormats().add(f);m.getRows().get(Integer.valueOf(2)).setFormatIndex(1);var a=run(b,m,o,null);assertEquals("/structure",a.differences().get(0).path());assertEquals(1,a.unresolved());assertEquals(3,a.result().getRows().size());}
    @Test public void repeatedColumnInsertionWithStableHeaderIsStructuralConflict(){var b=repeated(true,3);var m=repeated(true,3);var o=repeated(true,4);var f=MoxelFactory.eINSTANCE.createFormat();f.setWidth(42);m.getFormats().add(f);m.getRows().get(Integer.valueOf(0)).getCells().get(Integer.valueOf(2)).setFormatIndex(1);var a=run(b,m,o,null);assertEquals("/structure",a.differences().get(0).path());assertEquals(1,a.unresolved());assertEquals(3,a.result().getRows().get(Integer.valueOf(0)).getCells().size());}
}
